var data = typeof payload === 'string' ? JSON.parse(payload) : JSON.parse(String.fromCharCode.apply(null, payload));
var deviceName = metadata.topic.split('/')[0];

// SEC-03 (A-01): solo dispositivos cuyo nombre empieza por 'shellypro3em-'; cualquier otro tópico se descarta
// (no crea dispositivos ni escribe telemetría). Mismo criterio que el converter de Plus 1.
if (deviceName.indexOf('shellypro3em-') !== 0) {
    return null;
}

var result = {
    deviceName: deviceName,
    deviceType: 'Shelly Pro 3EM',
    telemetry: {}
};

var topic = metadata.topic;

if (topic.indexOf('/status/em:0') !== -1) {
    result.telemetry = {
        voltaje_fase_a:          data.a_voltage,
        corriente_fase_a:        data.a_current,
        potencia_activa_fase_a:  data.a_act_power,
        potencia_aparente_fase_a: data.a_aprt_power,
        factor_potencia_fase_a:  data.a_pf,
        voltaje_fase_b:          data.b_voltage,
        corriente_fase_b:        data.b_current,
        potencia_activa_fase_b:  data.b_act_power,
        potencia_aparente_fase_b: data.b_aprt_power,
        factor_potencia_fase_b:  data.b_pf,
        voltaje_fase_c:          data.c_voltage,
        corriente_fase_c:        data.c_current,
        potencia_activa_fase_c:  data.c_act_power,
        potencia_aparente_fase_c: data.c_aprt_power,
        factor_potencia_fase_c:  data.c_pf,
        potencia_activa_total:   data.total_act_power,
        potencia_aparente_total: data.total_aprt_power
    };
} else if (topic.indexOf('/status/emdata:0') !== -1) {
    result.telemetry = {
        energia_fase_a:     data.a_total_act_energy,
        energia_ret_fase_a: data.a_total_act_ret_energy,
        energia_fase_b:     data.b_total_act_energy,
        energia_ret_fase_b: data.b_total_act_ret_energy,
        energia_fase_c:     data.c_total_act_energy,
        energia_ret_fase_c: data.c_total_act_ret_energy,
        energia_total:      data.total_act,
        energia_ret_total:  data.total_act_ret
    };
}

return result;

